export async function setIssueParent(actor: Actor, input: SetIssueParentInput): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  const all = await issueRepo.listProjectHierarchy(input.orgId, issue.projectId);
  const below = descendants(issue.id, all);
  if (input.parentId !== null) {
    if (input.parentId === issue.id || below.some((item) => item.id === input.parentId)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const parent = await requireParent(input.orgId, issue.projectId, input.parentId);
    const height = below.reduce((max, item) => Math.max(max, levelOf(item, all) - levelOf(issue, all)), 0);
    if (levelOf(parent, all) + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  await emit("issue.updated", { ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId, changedFields: ["parentId"] });
  return after;
}

async function readHierarchy(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<{ issue: Issue; all: readonly Issue[] }> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return { issue, all: await issueRepo.listProjectHierarchy(orgId, issue.projectId) };
}

export async function listSubIssues(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  const { all } = await readHierarchy(actor, orgId, issueId);
  return all.filter((item) => item.parentId === issueId && item.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

export async function getIssueRollup(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  const { all } = await readHierarchy(actor, orgId, issueId);
  const live = descendants(issueId, all).filter((item) => item.archivedAt === null);
  const closed = live.filter(isClosed).length;
  return { total: live.length, open: live.length - closed, closed };
}

async function notifyParentIfCompleted(actor: Actor, child: Issue): Promise<void> {
  if (child.parentId === null) return;
  const parent = await issueRepo.findIssueById(actor.orgId, child.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) return;
  const all = await issueRepo.listProjectHierarchy(actor.orgId, parent.projectId);
  const live = descendants(parent.id, all).filter((item) => item.archivedAt === null);
  if (live.some((item) => !isClosed(item))) return;
  await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed", body: `All sub-issues of issue ${parent.id} are completed`,
    href: `/issues/${parent.id}`, actorId: actor.userId,
  });
}
